CREATE TRIGGER inbox_deferred_reinserted AFTER INSERT ON messages BEGIN
    DELETE FROM inbox_fill_deferred WHERE source_row=NEW.rowid;
  END

CREATE TRIGGER inbox_deferred_removed AFTER DELETE ON messages BEGIN
    DELETE FROM inbox_fill_deferred WHERE source_row=OLD.rowid;
  END

CREATE TRIGGER inbox_deferred_updated AFTER UPDATE ON messages BEGIN
    DELETE FROM inbox_fill_deferred WHERE source_row=OLD.rowid;
  END

CREATE TRIGGER inbox_project_delete AFTER DELETE ON messages WHEN (OLD.role='bot' AND (OLD.kind IN ('options','secret','connector','mcpSignIn','routine.run','goal.run','activity') OR (OLD.kind='text' AND instr(OLD.json,'artifactIds')>0))) BEGIN
    DELETE FROM inbox_raw WHERE thread_id=OLD.thread_id AND message_id=OLD.id;
  END

CREATE TRIGGER memory_disclosure_outputs_delete AFTER DELETE ON memory_disclosures BEGIN
 DELETE FROM memory_disclosure_outputs WHERE bundle_id=OLD.bundle_id;
END

CREATE TRIGGER memory_disclosure_outputs_update AFTER UPDATE OF output_message_ids,thread_id,bundle_id ON memory_disclosures BEGIN
 DELETE FROM memory_disclosure_outputs WHERE bundle_id=OLD.bundle_id AND (bundle_id!=NEW.bundle_id OR thread_id!=NEW.thread_id
  OR message_id NOT IN (SELECT value FROM json_each(NEW.output_message_ids) WHERE type='text'));
 INSERT OR IGNORE INTO memory_disclosure_outputs(bundle_id,thread_id,message_id)
 SELECT NEW.bundle_id,NEW.thread_id,value FROM json_each(NEW.output_message_ids) WHERE type='text';
END

CREATE TRIGGER memory_disclosure_refs_delete AFTER DELETE ON memory_disclosures BEGIN
 DELETE FROM memory_disclosure_refs WHERE bundle_id=OLD.bundle_id;
END

CREATE TRIGGER memory_disclosure_refs_update AFTER UPDATE OF bundle_id,state,record_versions,source_versions ON memory_disclosures
 WHEN OLD.bundle_id IS NOT NEW.bundle_id OR (OLD.state='revoked') IS NOT (NEW.state='revoked') OR OLD.record_versions IS NOT NEW.record_versions OR OLD.source_versions IS NOT NEW.source_versions BEGIN
 DELETE FROM memory_disclosure_refs WHERE bundle_id=OLD.bundle_id;
 INSERT INTO memory_disclosure_refs(bundle_id,kind,ref_id,ref_version) SELECT NEW.bundle_id,'record',json_extract(j.value,'$.id'),json_extract(j.value,'$.version') FROM json_each(NEW.record_versions) j WHERE NEW.state!='revoked' AND json_extract(j.value,'$.id') IS NOT NULL
 UNION ALL SELECT NEW.bundle_id,'source',json_extract(j.value,'$.id'),json_extract(j.value,'$.revision') FROM json_each(NEW.source_versions) j WHERE NEW.state!='revoked' AND json_extract(j.value,'$.id') IS NOT NULL;
END

CREATE TRIGGER memory_evidence_by_source_delete AFTER DELETE ON memory_evidence BEGIN
 DELETE FROM memory_evidence_by_source WHERE source_id=OLD.source_id AND source_revision=OLD.source_revision AND record_id=OLD.record_id AND record_version=OLD.record_version AND start_byte=OLD.start_byte;
END

CREATE TRIGGER memory_evidence_by_source_insert AFTER INSERT ON memory_evidence BEGIN
 INSERT OR IGNORE INTO memory_evidence_by_source VALUES(NEW.source_id,NEW.source_revision,NEW.record_id,NEW.record_version,NEW.start_byte);
END

CREATE TRIGGER memory_flow_capture AFTER INSERT ON memory_sources WHEN NEW.thread_id IS NOT NULL BEGIN
 INSERT OR IGNORE INTO memory_thread_flow(from_thread,to_thread,first_lsn) VALUES(NEW.thread_id,'scope:'||NEW.scope_id,coalesce((SELECT next FROM memory_lsn WHERE id=1),0));
END

CREATE TRIGGER memory_flow_record_scope AFTER UPDATE OF scope_id ON memory_records WHEN OLD.scope_id<>NEW.scope_id BEGIN
 INSERT OR IGNORE INTO memory_thread_flow(from_thread,to_thread,first_lsn) VALUES('scope:'||OLD.scope_id,'scope:'||NEW.scope_id,coalesce((SELECT next FROM memory_lsn WHERE id=1),0));
END

CREATE TRIGGER memory_flow_source_scope AFTER UPDATE OF scope_id ON memory_sources WHEN OLD.scope_id<>NEW.scope_id BEGIN
 INSERT OR IGNORE INTO memory_thread_flow(from_thread,to_thread,first_lsn) VALUES('scope:'||OLD.scope_id,'scope:'||NEW.scope_id,coalesce((SELECT next FROM memory_lsn WHERE id=1),0));
END

CREATE TRIGGER memory_open_turns_close AFTER UPDATE OF id,kind,outcome ON memory_sources WHEN NOT (NEW.kind='turn' AND NEW.outcome='working') BEGIN
 DELETE FROM memory_open_turns WHERE source_id=OLD.id;
END

CREATE TRIGGER memory_open_turns_delete AFTER DELETE ON memory_sources BEGIN
 DELETE FROM memory_open_turns WHERE source_id=OLD.id;
END

CREATE TRIGGER memory_open_turns_insert AFTER INSERT ON memory_sources WHEN NEW.kind='turn' AND NEW.outcome='working' BEGIN
 INSERT OR REPLACE INTO memory_open_turns(source_id,thread_id,turn_id,boot) VALUES(NEW.id,NEW.thread_id,NEW.turn_id,COALESCE((SELECT boot FROM memory_open_turns_build WHERE id=1),0));
END

CREATE TRIGGER memory_open_turns_keep AFTER UPDATE OF id,kind,outcome,thread_id,turn_id ON memory_sources WHEN NEW.kind='turn' AND NEW.outcome='working' BEGIN
 DELETE FROM memory_open_turns WHERE source_id=OLD.id AND OLD.id IS NOT NEW.id;
 INSERT INTO memory_open_turns(source_id,thread_id,turn_id,boot) VALUES(NEW.id,NEW.thread_id,NEW.turn_id,COALESCE((SELECT boot FROM memory_open_turns_build WHERE id=1),0))
  ON CONFLICT(source_id) DO UPDATE SET thread_id=excluded.thread_id, turn_id=excluded.turn_id;
END

CREATE TRIGGER memory_owner_tail_update AFTER UPDATE ON memory_records BEGIN
 DELETE FROM memory_owner_tail WHERE created_at=OLD.created_at AND record_id=OLD.id AND record_version=OLD.version;
 INSERT OR IGNORE INTO memory_owner_tail SELECT NEW.created_at,NEW.id,NEW.version WHERE (NEW.kind IN ('continuity-brief','commitment','self-trait','relation','pip-proposal','pip-counter','concern','episode') OR (NEW.kind='checkpoint' AND NEW.state!='active')); END

CREATE TRIGGER memory_receipt_flip AFTER UPDATE OF state ON memory_disclosures WHEN NEW.state='revoked' AND OLD.state IS NOT 'revoked' BEGIN
 INSERT OR IGNORE INTO memory_receipt_flips(thread_no,first_lsn,bundle_id) SELECT thread_no,first_lsn,bundle_id FROM memory_receipt_lines WHERE bundle_id=NEW.bundle_id;
END

CREATE TRIGGER memory_record_lsn_insert AFTER INSERT ON memory_records BEGIN
 INSERT OR IGNORE INTO memory_record_lsn(id,version,created_lsn) SELECT NEW.id,NEW.version,next FROM memory_lsn WHERE id=1;
END

CREATE TRIGGER memory_source_origins_insert AFTER INSERT ON memory_source_versions WHEN json_type(NEW.payload,'$.broughtFrom.sources')='array' BEGIN
 INSERT OR IGNORE INTO memory_source_origins SELECT json_extract(j.value,'$.id'),NEW.source_id FROM json_each(NEW.payload,'$.broughtFrom.sources') j WHERE json_type(j.value,'$.id')='text';
END

CREATE TRIGGER memory_watermark_bump AFTER UPDATE OF policy_revision,deletion_epoch ON memory_meta
 WHEN NEW.policy_revision IS NOT OLD.policy_revision OR NEW.deletion_epoch IS NOT OLD.deletion_epoch BEGIN
 UPDATE memory_lsn SET next=next+1 WHERE id=1;
 UPDATE memory_lineage_lsn_meta SET value=max(value,coalesce((SELECT next FROM memory_lsn WHERE id=1),0))
  WHERE (key='policy_bump_lsn' AND NEW.policy_revision IS NOT OLD.policy_revision) OR (key='epoch_bump_lsn' AND NEW.deletion_epoch IS NOT OLD.deletion_epoch);
 UPDATE memory_lineage_lsn_meta SET value=value+1 WHERE key='deny_generation';
END

CREATE TRIGGER setup_marks_delete AFTER DELETE ON messages WHEN (instr(OLD.json,'turnTerminal')>0 OR instr(OLD.json,'providerError')>0) BEGIN
    DELETE FROM setup_marks WHERE thread_id=OLD.thread_id AND message_id=OLD.id;
  END

CREATE TRIGGER shared_provenance_mark_request AFTER INSERT ON shared_request_provenance
BEGIN
  UPDATE room_requests SET shared_work=1 WHERE id=NEW.request_id AND verb IN ('ask','message') AND shared_work IS NOT 1;
  UPDATE room_requests SET shared_work=1 WHERE parent_id=NEW.request_id AND verb='wake' AND shared_work IS NOT 1;
END

CREATE TRIGGER turn_source_copy_d AFTER DELETE ON messages
 BEGIN
  INSERT INTO turn_source_holds(thread_id, position) SELECT thread_id, position FROM turn_source_copies WHERE origin_thread=OLD.thread_id AND origin_id=OLD.id;
  DELETE FROM turn_source_copies WHERE origin_thread=OLD.thread_id AND origin_id=OLD.id;
  DELETE FROM turn_source_copies WHERE thread_id=OLD.thread_id AND id=OLD.id;
 END

CREATE TRIGGER turn_source_hold_r BEFORE INSERT ON messages
 WHEN EXISTS (SELECT 1 FROM messages o WHERE o.thread_id=NEW.thread_id AND o.id=NEW.id AND o.role IS NOT 'user')
 BEGIN
  INSERT INTO turn_source_holds(thread_id, position) SELECT thread_id, rowid FROM messages WHERE thread_id=NEW.thread_id AND id=NEW.id;
  INSERT INTO turn_source_holds(thread_id, position) SELECT thread_id, position FROM turn_source_copies WHERE origin_thread=NEW.thread_id AND origin_id=NEW.id;
 END
